using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "Indigo Rite", menuName = "Data/Battle/Effects/Cellarius/Indigo Rite Effect")]
public class IndigoRiteEffect : Effect
{
	[SerializeField]
	private IndigoRiteAction indigoRiteAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), indigoRiteAction.DrawAmount);
	}
}
